class F90RoutineCallContainer(RoutineCallContainer):
    """F90 version of a RoutineCallContainer"""

    def get_call_string(self):
        """generate the call string"""
        return (
            f"call {self.get_call_name()}({', '.join(self.get_args_list())})"
        )


class F90KernelCallContainer(KernelCallContainer):
    """F90 version of a KernelCallContainer"""

    def get_call_string(self):
        """generate the call string"""
        return (
            f"call {self.get_call_name()}({', '.join(self.get_args_list())})"
        )


class F90AssignmentLine(AssignmentLine):
    """F90 version of an assignment line"""


class F90CodeLine(CodeLine):
    """F90 version of CodeLine"""


class F90CommentLine(CommentLine):
    """F90 version of CommentLine"""

    COMMENT_PREFIX = "! "

    # some_aux_variable = LibRoutineLocalVariable("testvar")


class F90MultiFrameContainer(MultiFrameContainer):
    """F90 version of MultiFrameContainer"""

    INDENT_BODY = True
    LOCAL_VARIABLE_CLASS = F90LocalVariable

    def generate_head_containers(self):
        if self._multiframe_variable is not None:
            yield from self.codelines_from_text(
                f"DO {self._multiframe_variable.expr()} = {self._min_value}, {self._max_value-1}"
            )

    def generate_foot_containers(self):
        if self._multiframe_variable is not None:
            yield from self.codelines_from_text(
                f"END DO  ! {self._multiframe_variable.expr()}"
            )


class F90RoutineContainer(RoutineContainer):
    """F90 version of a RoutineContainer"""

    INDENT_BODY = True
    DEFAULT_MULTIFRAME_CLASS = F90MultiFrameContainer

    def generate_head_containers(self, **_):
        call_args = (
            var.as_argument() for var in self.get_argument_variables()
        )
        yield F90CommentLine(f"Subroutine: {self.name}", context=self.context)
        yield from self.codelines_from_text(
            f"SUBROUTINE {self.name}({', '.join(call_args)})"
        )

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text(f"END SUBROUTINE {self.name}")


class F90KernelContainer(KernelContainer):
    """F90 version of a KernelContainer"""

    INDENT_BODY = True
    INPUT_VARIABLE_CLASS = F90InputVariable

    def generate_head_containers(self, **_):
        call_args = (
            var.as_argument() for var in self.get_argument_variables()
        )
        yield F90CommentLine(f"Kernel: {self.name}", context=self.context)
        yield from self.codelines_from_text(
            f"SUBROUTINE {self.name}({', '.join(call_args)})"
        )

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text(f"END SUBROUTINE {self.name}")


class F90AffineContainer(StatementLine):
    INDENT_BODY = False
    BLUEPRINT = "{y_expression} = {y_expression} + {a_value} * {x_expression} + {b_value}"

    def __init__(self, y, yo, a, x, xo, b, *, context, **params):
        super().__init__(
            {
                "y_expression": y.at(*yo),
                "x_expression": x.at(*xo),
                "a_value": a,
                "b_value": b,
            },
            context=context,
            **params,
        )
        self.requires(y)
        self.requires(x)


class F90BilinearContainer(StatementLine):
    INDENT_BODY = False
    BLUEPRINT = "{y_expression} = {y_expression} + {a_value} * {u_expression} * {v_expression}"

    def __init__(self, y, yo, a, u, uo, v, vo, *, context, **params):
        super().__init__(
            {
                "y_expression": y.at(*yo),
                "u_expression": u.at(*uo),
                "v_expression": v.at(*vo),
                "a_value": str(a) if a > 0 else f"({a})",
            },
            context=context,
            **params,
        )
        self.requires(y)
        self.requires(u)
        self.requires(v)


class F90ImportContainer(ImportContainer):
    """F90 version for imports"""

    INDENT_BODY = False

    def construct_code_lines(self, **_):
        """create the codelines required for the import"""
        yield f"use {self.library.name}"


