class F90Builder(Builder, identifier="FORTRAN90"):
    """F90 Builder"""

    def create_libroutine_variable(
        self, *, name, dtype, status, size, assignment=None, **kwargs
    ):
        status = status & 3
        if status == LibRoutineVariable.STATUS_INPUT:
            return F90InputVariable(
                name=name, dtype=dtype, size=size, assignment=assignment
            )
        elif status == LibRoutineVariable.STATUS_OUTPUT:
            return F90OutputVariable(
                name=name, dtype=dtype, size=size, assignment=assignment
            )
        elif status == LibRoutineVariable.STATUS_INOUT:
            return F90InOutVariable(
                name=name, dtype=dtype, size=size, assignment=assignment
            )
        else:
            return super().create_libroutine_variable(
                name=name, dtype=dtype, status=status, size=size
            )

    def handle_environment_instruction(self, instruction, context, buildargs):
        yield from super().handle_environment_instruction(
            instruction, context, buildargs
        )

    def handle_affine_instruction(self, instruction, context, buildargs):
        instruction_dict = instruction.apply_environment(
            context.environment
        ).contribute_to_dict()

        tgt0 = instruction_dict.get("tgt0")
        src0 = instruction_dict.get("src0")
        alpha = instruction_dict.get("alpha")
        beta = instruction_dict.get("beta")
        otgt = list(tgt0.offsets)
        osrc = list(src0.offsets)
        yield F90CommentLine(f"tgt0={tgt0.name} @ {otgt}", context=context)
        yield F90CommentLine(f"src0={src0.name} @ {osrc}", context=context)
        yield F90CommentLine(f"alpha = {alpha}", context=context)
        yield F90CommentLine(f"beta  = {beta}", context=context)
        x_var_real = context.namespace.find_assignment(type(src0), "real")
        x_var_imag = context.namespace.find_assignment(type(src0), "imag")
        y_var_real = context.namespace.find_assignment(type(tgt0), "real")
        y_var_imag = context.namespace.find_assignment(type(tgt0), "imag")
        # print("find assignment", x_var_real, y_var_real)
        # print(context.environment)
        x_var_offs = src0.offsets
        y_var_offs = tgt0.offsets
        a_real = alpha.real
        a_imag = alpha.imag
        b_real = beta.real
        b_imag = beta.imag

        hook = HookContainer(context=context)

        hook.requires(x_var_real)
        hook.requires(x_var_imag)
        hook.requires(y_var_real)
        hook.requires(y_var_imag)

        yield F90AffineContainer(
            y_var_real,
            y_var_offs,
            a_real,
            x_var_real,
            x_var_offs,
            0.0,
            context=context,
        )
        yield F90AffineContainer(
            y_var_real,
            y_var_offs,
            -a_imag,
            x_var_imag,
            x_var_offs,
            b_real,
            context=context,
        )
        yield F90AffineContainer(
            y_var_imag,
            y_var_offs,
            a_real,
            x_var_imag,
            x_var_offs,
            0.0,
            context=context,
        )
        yield F90AffineContainer(
            y_var_imag,
            y_var_offs,
            a_imag,
            x_var_real,
            x_var_offs,
            b_imag,
            context=context,
        )
        yield CodeLine("", context=context)

    def handle_bilinear_instruction(self, instruction, context, buildargs):
        instruction_dict = instruction.apply_environment(
            context.environment
        ).contribute_to_dict()

        tgt0 = instruction_dict.get("tgt0")
        src0 = instruction_dict.get("src0")
        src1 = instruction_dict.get("src1")
        alpha = instruction_dict.get("alpha")
        otgt0 = list(tgt0.offsets)
        osrc0 = list(src0.offsets)
        osrc1 = list(src1.offsets)
        u_var_real = context.namespace.find_assignment(type(src0), "real")
        u_var_imag = context.namespace.find_assignment(type(src0), "imag")
        v_var_real = context.namespace.find_assignment(type(src1), "real")
        v_var_imag = context.namespace.find_assignment(type(src1), "imag")
        y_var_real = context.namespace.find_assignment(type(tgt0), "real")
        y_var_imag = context.namespace.find_assignment(type(tgt0), "imag")

        u_var_offs = src0.offsets
        v_var_offs = src1.offsets
        y_var_offs = tgt0.offsets
        a_real = alpha.real
        a_imag = alpha.imag

        include_all = False

        hook = HookContainer(context=context)

        hook.requires(u_var_real)
        hook.requires(u_var_imag)
        hook.requires(v_var_real)
        hook.requires(v_var_imag)
        hook.requires(y_var_real)
        hook.requires(y_var_imag)

        if abs(a_real) > 1e-12 or include_all:
            yield F90BilinearContainer(
                y_var_real,
                y_var_offs,
                a_real,
                u_var_real,
                u_var_offs,
                v_var_real,
                v_var_offs,
                context=context,
            )
            yield F90BilinearContainer(
                y_var_real,
                y_var_offs,
                -a_real,
                u_var_imag,
                u_var_offs,
                v_var_imag,
                v_var_offs,
                context=context,
            )

        if abs(a_imag) > 1e-12 or include_all:
            yield F90BilinearContainer(
                y_var_real,
                y_var_offs,
                -a_imag,
                u_var_imag,
                u_var_offs,
                v_var_real,
                v_var_offs,
                context=context,
            )
            yield F90BilinearContainer(
                y_var_real,
                y_var_offs,
                -a_imag,
                u_var_real,
                u_var_offs,
                v_var_imag,
                v_var_offs,
                context=context,
            )

        if abs(a_real) > 1e-12 or include_all:
            yield F90BilinearContainer(
                y_var_imag,
                y_var_offs,
                a_real,
                u_var_imag,
                u_var_offs,
                v_var_real,
                v_var_offs,
                context=context,
            )
            yield F90BilinearContainer(
                y_var_imag,
                y_var_offs,
                a_real,
                u_var_real,
                u_var_offs,
                v_var_imag,
                v_var_offs,
                context=context,
            )

        if abs(a_imag) > 1e-12 or include_all:
            yield F90BilinearContainer(
                y_var_imag,
                y_var_offs,
                a_imag,
                u_var_real,
                u_var_offs,
                v_var_real,
                v_var_offs,
                context=context,
            )
            yield F90BilinearContainer(
                y_var_imag,
                y_var_offs,
                -a_imag,
                u_var_imag,
                u_var_offs,
                v_var_imag,
                v_var_offs,
                context=context,
            )
        yield CodeLine("", context=context)

    def create_external_array(
        self,
        *args,
        context,
        **kwargs,
    ):
        return super().create_external_array(
            *args,
            context=context,
            local_class=F90LocalVariable,
            constant_class=F90Constant,
        )


F90Builder.set_instruction_class_handler(
    AffineOperationInstruction, F90Builder.handle_affine_instruction
)
F90Builder.set_instruction_class_handler(
    BiLinearOperationInstruction, F90Builder.handle_bilinear_instruction
)

F90RoutineContainer.set_comment_class(None)
F90KernelContainer.set_comment_class(None)

F90Builder.set_comment_class(F90CommentLine)
F90Builder.set_routinecall_class(F90RoutineCallContainer)
F90Builder.set_kernelcall_class(F90KernelCallContainer)
F90Builder.set_mfcontainer_class(F90MultiFrameContainer)

